      "file": "t14.js",
      "line": 5,
      "evidence": "document.title = \"Search: \" + term.length + \" characters\";",
      "llm_reasoning": "While minor, exposing the exact length of a search query in the document title can potentially be used in side-channel attacks or fingerprinting if the query length is sensitive.",
      "suggested_fix": "Consider if exposing the query length is necessary; if not, remove it or use a generic title."
    }
